Assume A:cont-A:attractor. There exist $\alpha_0>0$ and constants $c_1,c_2,c_3,c_4>0$ such that for all $\alpha<\alpha_0$, $i\in\{1,2,3\}$ and $n$, 
    \begin{enumerate}[label=(\roman*)]
        \item $\sum_{n=0}^\infty e^{-c_2\alpha n} \le c_3/\alpha$.
        \item For all $h\in$, the $i$th derivative of $h\circ\varphi_n$ satisfies:
        \begin{align*}
            \left\|D^i(h\circ\varphi_n)\right\| \le c_1 e^{-c_2\alpha n},
        \end{align*}
        \end{enumerate}

Assume A:mart--A:attractor. Then, there exists a constant $C>0$ and $\alpha_0$ such that for all $n$, $\alpha\le\alpha_0$ and all $i\in\{1,2,3\}$, $h\in$ and $g\in$:
    \begin{align}

        \left|\mathbb{E}\left[\sum_{k=0}^{n-1}D^i(h \circ \varphi_{n-(k+1)})(\theta_{k})\left( g(\theta_{k+1}, X_{k+1}) - g(\theta_{k}, X_{k}) \right)\right]\right|\le C.
    \end{align}

Assume A:mart--A:attractor. Then, there exists a constant $C>0$ and $\alpha_0$ such that for all $n$, $\alpha\le\alpha_0$:
    \begin{align}
        \forall\ell\in: \qquad
        &\frac1n \sum_{k=0}^{n-1}\mathbb{E}\left[\ell(\theta_{k},X_{k})- \bar{\ell}(\theta_{k})\right] \leq C(\frac{1}{n}+\alpha).
        \\
        \forall\ell\in: \qquad
        &\frac1n \sum_{k=0}^{n-1}\mathbb{E}\left[\ell(\theta_{k},X_{k})- \bar{\ell}(\theta_{k}) + \alpha \bar{m}(\theta_k)\right] \leq C(\frac{1}{n}+\alpha^2),
    \end{align}
    where $\bar{m}=\sum_{x,x'\in\mathcal{X}} DG_\ell(\theta, x') (f(\theta,x) + R(\theta,x,x'))K_{x,x'}(\theta)\pi_x(\theta)$.

Assume A:mart--A:attractor. Then, there exists a constant $C>0$ and $\alpha_0$ such that for all $n$, $\alpha\le\alpha_0$, $h\in$ and $g\in$:
    \begin{align*}
        \left|\frac1N\sum_{n=1}^N \sum_{k=0}^{n-1}D(h\circ\varphi_{n-(k+1)})(\theta_{k}) (g(\theta_k,X_k)-\bar{g}(\theta_k)) - \sum_{k=0}^{N-1} \bar{m}(\theta_k)\right| \le C\left(\alpha+\frac{1}{N\alpha^2}\right),
    \end{align*}
    where the function $\bar{m}$ is equal to 
    \begin{align*}
        \bar{m}(\theta) = \sum_{x,x'\in\mathcal{X}} \sum_{n=0}^\infty D\bigl(D(h\circ\phi_n)(\theta) G_g(\theta, x')\bigr)\bigl(f(\theta,x)+R(\theta,x,x')\bigr)K_{x,x'}(\theta)\pi_x(\theta).
    \end{align*}

Assume A:mart--A:attractor. Then, there exists a constant $C>0$ and $\alpha_0$ such that for all $n$, $\alpha\le\alpha_0$ and all $h\in$:
    \begin{align*}
        \left|\mathbb{E}\left[h(\theta_n) - h(\phi_{n\alpha}(\theta_0))\right] - \alpha V^{(\alpha)}_{n}\right| \le C\alpha^2,
    \end{align*}
    where the quantity $V^{(\alpha)}_{n}$ is given by:
    \begin{align*}
        V^{(\alpha)}_{n} := \sum_{k=0}^{n-1} &\mathbb{E}\Big[D(h\circ\varphi_{n-(k+1)})(\theta_{k})(f(\theta_{k},X_{k})-\bar{f}(X_{k}))\\
        &\quad - D^2(h\circ\varphi_{n-(k+1)})(\theta_{k}) \left((f (\theta_{k},X_{k})-\bar{f}(X_{k}))^{\otimes 2} + Q(\theta_{k},X_{k})\right)\Big].
    \end{align*}

    Moreover, $V^{(\alpha)}_n$ is bounded independently of $\alpha$ and $n$.

Assume A:mart--A:attractor. Then, there exist a constant $C>0$ and $\alpha_0>0$ such that for all $h\in$, there exists a vector $V$ such that for all $n$, $\alpha\le\alpha_0$:
    \begin{align*}
        \left|\overline{V}^{(\alpha)}_n - V\right| \le C(\alpha + \frac1{n\alpha}),
    \end{align*}
    where $\overline{V}^{(\alpha)}_n := n^{-1}\sum_{k=1}^{n}V^{(\alpha)}_k$ with $V^{(\alpha)}_k$ as in Proposition~prop:Vn.

Assume A:mart--A:attractor. Then, there exists a constant $C>0$ and $\alpha_0$ such that for all $n$, $\alpha\le\alpha_0$ and all $h\in$:
    \begin{align*}
        \left|\mathbb{E}\left[h(\theta_n) - h(\phi_{\alpha n}(\theta_0))\right] \right| \leq \alpha C.
    \end{align*}

Assume A:mart--A:attractor. Then, there exists a constant $C'>0$ and $\alpha_0$ such that for all $\alpha\le\alpha_0$ and $h\in$:
    \begin{align}
        \limsup_{n\to\infty}\left|\frac{1}{n}\sum_{k=1}^{n}\mathbb{E}\left[h(\theta_{k})\right] - h(\theta^*) - \alpha V\right| & \leq \alpha^2 C'. 
    \end{align}

Assume A:mart--A:attractor. Then, there exists a constant $C''>0$ and $\alpha_0$ such that for all $\alpha\le\alpha_0$:
    \begin{align*}
        \lim_{n\to\infty} \mathbf{P}\left(\left|\bar{\theta}_n - (\theta^* + \alpha V)\right| \ge C''\alpha^2\right) = 0. 
    \end{align*}

Assume A:mart--A:attractor. Define 
    \begin{align}
        V = D h(\theta^*) \bigl(H^{(1)}\bigr)^{-1} ( S + H^{(2)} \cdot W) + D^2 h(\theta^*) \cdot W 
    \end{align}
    with $H^{(1)}_{i,j} := \frac{\partial \bar{f}_i}{\partial \theta_i}(\theta^*)$ is the Jacobien matrix of $\bar{f}$ at $\theta^*$, $H^{(2)}_{i,jk} = \frac{\partial \bar{f}_i}{\partial \theta_i\partial \theta_j}(\theta^*)$ is the second derivative of $\bar{f}$ in $\theta^*$. In the above notation, $H^{(2)} \cdot W := (\sum_{j,k} H^{(2)}_{i,jk} W_{j,k})_{i=1...d}$, where $W$ is the unique solution to the Sylvester equation $H^{(1)}W + W\bigl(H^{(1)}\bigr)^T + O = 0$ and where $O$ and $S$ are defined by
    \begin{align}
        O & := \sum_{x,x'} G_f (\theta^*, x') \bigl(f(\theta^*, x) + R(\theta^*,x,x')\bigr)^T K(\theta^*)_{x,x'}\pi_x(\theta^*)   + \bar{g}(\theta^*), \\
        S & := \sum_{x,x'} \bigl( f(\theta^*, x) + R(\theta^*,x,x') \bigr) DG_f (\theta^*, x')^T K(\theta^*)_{x,x'} \pi_x(\theta^*) 
    \end{align}
    with  $\bar{g}(\theta^*) := \sum_x \pi_x(\theta^*)\Bigr((f(\theta^*,x) - \bar{f}(\theta^*))^{\otimes2} + Q(\theta^*, x)\Bigl)$ is defined as in the proof of Proposition~prop:V.

    There exists a constant $C>0$ and $\alpha_0$ such that for all $\alpha\le\alpha_0$:
    \begin{align*}
        \left|V-V^{(\alpha)}\right|\le C\alpha,
    \end{align*}
    where $V^{(\alpha)} = \alpha(\sum_{k=0}^{\infty} D^2(h\circ\varphi_{k})(\theta^*)\bar{g}(\theta^*) + m(\theta^*))$ is defined as in the proof of Proposition~prop:V.

Assume A:mart--A:attractor. Then, there exists a constant $C>0$ and $\alpha_0$ such that for all $n$, $\alpha\le\alpha_0$ and all $i\in\{1,2,3\}$, $h\in$ and $g\in$:
    \begin{align}
        & \left| \sum_{k=0}^{n-1}\mathbb{E}\left[D^i(h \circ \varphi_{n-(k+1)})(\theta_{k}) \Bigl( g(\theta_{k},X_{k})- \bar{g}(\theta_{k}) \Bigr)\right] \right| \leq C. 
    \end{align}
